/**
 * Generated by the ship-workflow test coverage audit (PR #716).
 *
 * The profile page's two ADAPT-template seams: the delete confirmation that names how many templates
 * the profile's ON DELETE CASCADE takes with it (design D14), and the `?tab=adapt-templates` link
 * `templatesPageHref` builds for a profile scope.
 */
import { act, fireEvent, render, screen, within } from '@testing-library/react';
import ProfileDetailsPage from '../page';
import { fetchProfile } from '@/lib/profiles';
import { templatesPageHref } from '@/lib/compare-templates';

const PROFILE = 'dddddddd-0000-4000-8000-00000000000d';
let mockSearch = new URLSearchParams();

jest.mock('next/navigation', () => ({
  useRouter: () => ({ push: jest.fn() }),
  useParams: () => ({ id: 'dddddddd-0000-4000-8000-00000000000d' }),
  useSearchParams: () => ({ get: (name: string) => mockSearch.get(name) }),
}));

jest.mock('@/lib/profiles', () => ({ deleteProfile: jest.fn(), fetchProfile: jest.fn() }));

// The panel fetches on mount; a marker is enough to see which scope it was handed.
jest.mock('@/app/settings/profiles/adapt-templates/components/AdaptTemplatesPanel', () => ({
  AdaptTemplatesPanel: ({ scope }: { scope: { kind: string; profileId?: string } }) => (
    <div data-testid="adapt-panel">{`${scope.kind}:${scope.profileId}`}</div>
  ),
}));

jest.mock('@/app/settings/profiles/[id]/components', () => ({
  ProfileDashboardsTable: () => null,
  DashboardFormDialog: () => null,
  ProfileBenchmarksTable: () => null,
  BenchmarkFormDialog: () => null,
  BatchDeleteDialog: () => null,
  ProfileTagChips: () => null,
  TabPanel: ({ value, index, children }: { value: number; index: number; children?: React.ReactNode }) =>
    value === index ? <div role="tabpanel">{children}</div> : null,
}));

const profile = {
  id: PROFILE, name: 'jvm', description: '', tags: ['jvm'], readOnly: false, organizationId: 'org-a',
  dashboardCount: 0, sloCount: 0, deepLinksCount: 0, adaptTemplateCount: 1, createdAt: '', updatedAt: '',
};

jest.mock('@/app/settings/profiles/[id]/hooks', () => {
  const list = { loading: false, error: null, selectedIds: new Set(), formDialogOpen: false, batchDeleteDialogOpen: false };
  return {
    useProfileData: () => ({ profile: mockProfileRef.current, loading: false, error: null }),
    useGrafanaData: () => ({ loadGrafanaData: jest.fn(), dashboards: [], instances: [], loading: false }),
    useDashboards: () => ({ ...list, dashboards: [], loadDashboards: jest.fn() }),
    useBenchmarks: () => ({ ...list, benchmarks: [], loadBenchmarks: jest.fn() }),
  };
});
const mockProfileRef: { current: typeof profile } = { current: profile };

const mockFetchProfile = fetchProfile as jest.MockedFunction<typeof fetchProfile>;

describe('ProfileDetailsPage: ADAPT templates', () => {
  beforeEach(() => {
    mockSearch = new URLSearchParams();
    mockProfileRef.current = profile;
    mockFetchProfile.mockReset();
  });

  /**
   * Value: protects=the profile delete confirmation names the ADAPT templates the cascade deletes, counted when it opens;
   *   fails_when=the button stops reading a fresh count (opens the dialog directly, or keeps the page-load count),
   *   or the dialog's Delete is live before that fresh count has arrived;
   *   why_new=cascade-templates.test pins the sentence only; nothing rendered the page's wiring of it;
   *   seam=none; no_claim=the API's count query, or the profiles list page (which shows no count).
   */
  it('names the ADAPT templates the delete takes with it, counted fresh when the confirmation opens', async () => {
    // The page loaded with one template; three more were added on the tab since. The fresh read is held
    // open so the dialog can be checked before it lands.
    let resolveFresh!: (fresh: typeof profile) => void;
    mockFetchProfile.mockReturnValue(new Promise((resolve) => { resolveFresh = resolve; }) as never);
    render(<ProfileDetailsPage />);

    fireEvent.click(screen.getByRole('button', { name: /delete profile/i }));

    const dialog = await screen.findByRole('dialog');
    const confirm = within(dialog).getByRole('button', { name: 'Delete' });
    expect(confirm).toBeDisabled();

    await act(async () => resolveFresh({ ...profile, adaptTemplateCount: 4 }));

    expect(await within(dialog).findByText(/It also deletes its 4 ADAPT templates/)).toBeInTheDocument();
    expect(confirm).toBeEnabled();
    expect(mockFetchProfile).toHaveBeenCalledWith(PROFILE);
  });

  /**
   * Value: protects=templatesPageHref's profile link (?tab=adapt-templates) opens that profile's templates tab;
   *   fails_when=the page's tab-param map and the link builder drift apart, landing the link on Dashboards;
   *   why_new=lib/compare-templates.test pins the href only; the page side of the same contract was untested;
   *   seam=none; no_claim=what the panel itself renders or fetches (stubbed here).
   */
  it('opens the ADAPT templates tab, on the profile’s own templates, from ?tab=adapt-templates', () => {
    mockSearch = new URL(templatesPageHref({ kind: 'profile', profileId: PROFILE }), 'http://localhost').searchParams;
    render(<ProfileDetailsPage />);

    expect(screen.getByRole('tab', { name: 'ADAPT templates' })).toHaveAttribute('aria-selected', 'true');
    expect(screen.getByTestId('adapt-panel')).toHaveTextContent(`profile:${PROFILE}`);
  });
});
